package com.nextfeet.nextfeet.controller; import jakarta.servlet.http.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import com.nextfeet.nextfeet.model.*; import com.nextfeet.nextfeet.service.*; @Controller public class ClienteController {private final UsuarioService users;private final ZapatillaService shoes;private final CategoriaService cats;private final PedidoService orders; public ClienteController(UsuarioService u,ZapatillaService z,CategoriaService c,PedidoService o){users=u;shoes=z;cats=c;orders=o;} private Usuario user(HttpSession s){return (Usuario)s.getAttribute("usuario");} @GetMapping("/home") public String home(Model m){m.addAttribute("zapatillas",shoes.catalogo(null,null,null,null,null));return "home";} @GetMapping("/perfil") public String perfil(HttpSession s,Model m){m.addAttribute("usuario",users.obtener(user(s).getId()));return "cliente/perfil";} @PostMapping("/perfil") public String actualizar(@ModelAttribute Usuario u,HttpSession s){u.setId(user(s).getId());users.actualizar(u);s.setAttribute("usuario",users.obtener(u.getId()));return "redirect:/perfil";} @PostMapping("/perfil/desactivar") public String desactivar(HttpSession s){users.desactivar(user(s).getId());s.invalidate();return "redirect:/login";} @GetMapping("/catalogo") public String catalogo(@RequestParam(required=false)String q,@RequestParam(required=false)String marca,@RequestParam(required=false)Integer categoria,@RequestParam(required=false)Double min,@RequestParam(required=false)Double max,Model m){m.addAttribute("zapatillas",shoes.catalogo(q,marca,categoria,min,max));m.addAttribute("categorias",cats.listar());return "cliente/catalogo";} @GetMapping("/producto/{id}") public String producto(@PathVariable Integer id,Model m){m.addAttribute("zapatilla",shoes.obtener(id));return "cliente/producto";} @GetMapping("/ofertas") public String ofertas(Model m){m.addAttribute("ofertas",java.util.Collections.emptyList());m.addAttribute("zapatillas",shoes.catalogo(null,null,null,null,null));return "cliente/ofertas";} @GetMapping("/nosotros") public String nosotros(){return "cliente/nosotros";} @GetMapping("/contacto") public String contacto(){return "cliente/contacto";} @GetMapping("/publicidad") public String publicidad(){return "cliente/publicidad";} @GetMapping("/pedidos") public String pedidos(HttpSession s,Model m){m.addAttribute("pedidos",orders.listarPorUsuario(user(s).getId()));return "cliente/pedidos";} @GetMapping("/pedido/{id}") public String pedido(@PathVariable Integer id,Model m){m.addAttribute("pedido",orders.obtener(id));return "cliente/pedido";} }